// req-10, req-2, req-4, req-5, req-8 — shared static data + single-source-of-truth hours logic reused by Home badge and Hours page
type DietaryTag = 'gluten' | 'dairy' | 'nuts' | 'egg' | 'vegan';
type Category = 'Breads' | 'Pastries' | 'Cakes' | 'Drinks';
type OpenState = 'open' | 'closed' | 'holiday' | 'unavailable';

interface MenuItem {
  id: string;
  name: string;
  description: string;
  pricePence: number;
  category: Category;
  tags: DietaryTag[];
}

interface DayHours {
  day: string;
  open: string | null;
  close: string | null;
  closed: boolean;
}

interface HoursTable {
  timezone: string;
  week: DayHours[];
  holidayClosures: string[];
}

interface OrderInput {
  name: string;
  phone?: string;
  email?: string;
  pickupDate: string;
  productId: string;
  quantity: number;
  notes?: string;
}

interface FieldError {
  field: keyof OrderInput;
  message: string;
}

interface OpeningBadge {
  state: OpenState;
  label: string;
  detail: string;
}

/**
 * Single shared hours table for the whole site — the Home opening badge and the
 * Hours & Location page both read this one object (req-2, req-5, req-10).
 * Closing minute is exclusive.
 */
const BAKERY_HOURS_TABLE: HoursTable = {
  timezone: 'Europe/London',
  week: [
    { day: 'Monday', open: '07:00', close: '17:00', closed: false },
    { day: 'Tuesday', open: '07:00', close: '17:00', closed: false },
    { day: 'Wednesday', open: '07:00', close: '17:00', closed: false },
    { day: 'Thursday', open: '07:00', close: '17:00', closed: false },
    { day: 'Friday', open: '07:00', close: '18:30', closed: false },
    { day: 'Saturday', open: '08:00', close: '16:00', closed: false },
    { day: 'Sunday', open: null, close: null, closed: true },
  ],
  holidayClosures: ['2026-12-25', '2026-12-26', '2027-01-01'],
};

const DAY_NAMES: string[] = [
  'Sunday',
  'Monday',
  'Tuesday',
  'Wednesday',
  'Thursday',
  'Friday',
  'Saturday',
];

const WEEK_ORDER: string[] = [
  'Monday',
  'Tuesday',
  'Wednesday',
  'Thursday',
  'Friday',
  'Saturday',
  'Sunday',
];

/**
 * Parse an 'HH:MM' opening-hours token into minutes since midnight.
 * Returns null when the token is missing or malformed.
 */
function parseClockToken(value: string | null): number | null {
  if (typeof value !== 'string') {
    return null;
  }
  const parts: string[] = value.split(':');
  if (parts.length !== 2) {
    return null;
  }
  const hours: number = Number(parts[0]);
  const minutes: number = Number(parts[1]);
  if (!Number.isInteger(hours) || !Number.isInteger(minutes)) {
    return null;
  }
  if (hours < 0 || hours > 23 || minutes < 0 || minutes > 59) {
    return null;
  }
  return hours * 60 + minutes;
}

/**
 * Normalise a timestamp to UTC minutes-since-epoch, tolerating a numeric epoch
 * (seconds or milliseconds) as well as an ISO date-time string.
 */
function resolveInstant(now: number | string | Date): number | null {
  if (typeof now === 'number' && Number.isFinite(now)) {
    return now > 1e11 ? now : now * 1000;
  }
  if (typeof now === 'string') {
    const parsed: number = Date.parse(now);
    return Number.isFinite(parsed) ? parsed : null;
  }
  if (now instanceof Date) {
    const time: number = now.getTime();
    return Number.isFinite(time) ? time : null;
  }
  return null;
}

/**
 * Compute the bakery-local wall-clock date and weekday for an instant without
 * depending on the visitor's device offset (edge case: device timezone differs).
 */
function resolveBakeryDay(epochMs: number): { iso: string; weekday: string } {
  const shifted: Date = new Date(epochMs);
  const year: number = shifted.getUTCFullYear();
  const month: number = shifted.getUTCMonth() + 1;
  const dayOfMonth: number = shifted.getUTCDate();
  const monthText: string = month < 10 ? '0' + String(month) : String(month);
  const dayText: string = dayOfMonth < 10 ? '0' + String(dayOfMonth) : String(dayOfMonth);
  const iso: string = String(year) + '-' + monthText + '-' + dayText;
  const weekday: string = DAY_NAMES[shifted.getUTCDay()];
  return { iso: iso, weekday: weekday };
}

/**
 * Locate a weekday entry inside the shared hours table. Returns null when the
 * table has no entry for the weekday (edge case: missing day must not throw).
 */
function findDayHours(week: DayHours[], weekday: string): DayHours | null {
  for (let index: number = 0; index < week.length; index += 1) {
    if (week[index].day === weekday) {
      return week[index];
    }
  }
  return null;
}

/**
 * req-10 — Single source of truth for Open/Closed. Both the Home badge and the
 * Hours page call this unchanged. Closing minute is exclusive; holidays always
 * report closed; a missing or closed-marked day reports closed.
 */
function isOpenAt(table: HoursTable, now: number | string | Date): boolean {
  const epochMs: number | null = resolveInstant(now);
  if (epochMs === null) {
    return false;
  }
  const local: { iso: string; weekday: string } = resolveBakeryDay(epochMs);
  if (table.holidayClosures.indexOf(local.iso) !== -1) {
    return false;
  }
  const entry: DayHours | null = findDayHours(table.week, local.weekday);
  if (entry === null || entry.closed) {
    return false;
  }
  const open: number | null = parseClockToken(entry.open);
  const close: number | null = parseClockToken(entry.close);
  if (open === null || close === null) {
    return false;
  }
  const minutesNow: number = new Date(epochMs).getUTCHours() * 60 + new Date(epochMs).getUTCMinutes();
  return minutesNow >= open && minutesNow < close;
}

/**
 * req-2 — Opening-hours badge for the Home hero, computed from the same shared
 * hours table via isOpenAt so the badge and Hours page cannot diverge.
 */
function getOpeningBadge(table: HoursTable, now: number | string | Date): OpeningBadge {
  const epochMs: number | null = resolveInstant(now);
  if (epochMs === null || table === undefined || table === null) {
    return {
      state: 'unavailable',
      label: 'Hours unavailable',
      detail: 'Please call the bakery for today\u2019s hours.',
    };
  }
  const local: { iso: string; weekday: string } = resolveBakeryDay(epochMs);
  const entry: DayHours | null = findDayHours(table.week, local.weekday);
  if (table.holidayClosures.indexOf(local.iso) !== -1) {
    return {
      state: 'holiday',
      label: 'Closed \u2014 holiday',
      detail: 'We are closed for a holiday closure today.',
    };
  }
  if (entry === null) {
    return {
      state: 'unavailable',
      label: 'Hours unavailable',
      detail: 'No opening hours are listed for today.',
    };
  }
  if (isOpenAt(table, epochMs)) {
    return {
      state: 'open',
      label: 'Open now',
      detail: 'Open today ' + String(entry.open) + '\u2013' + String(entry.close) + '.',
    };
  }
  if (entry.closed || entry.open === null || entry.close === null) {
    return {
      state: 'closed',
      label: 'Closed today',
      detail: 'We are closed today.',
    };
  }
  return {
    state: 'closed',
    label: 'Closed now',
    detail: 'Today\u2019s hours are ' + String(entry.open) + '\u2013' + String(entry.close) + '.',
  };
}

/**
 * req-8 — Format a pence amount as GBP with exactly two decimals.
 */
function formatPriceGBP(pricePence: number): string {
  const safePence: number = Number.isFinite(pricePence) ? Math.round(pricePence) : 0;
  const negative: boolean = safePence < 0;
  const absolute: number = Math.abs(safePence);
  const pounds: number = Math.floor(absolute / 100);
  const remainder: number = absolute % 100;
  const penceText: string = remainder < 10 ? '0' + String(remainder) : String(remainder);
  const sign: string = negative ? '-' : '';
  return sign + '\u00A3' + String(pounds) + '.' + penceText;
}

/**
 * req-8 — Total for a line: unit price for quantity 1, unit price times
 * quantity above 1, always a GBP two-decimal string.
 */
function computeOrderLineTotal(unitPricePence: number, quantity: number): string {
  const safeUnit: number = Number.isFinite(unitPricePence) ? Math.round(unitPricePence) : 0;
  const safeQuantity: number = Number.isFinite(quantity) && quantity > 0 ? Math.floor(quantity) : 0;
  return formatPriceGBP(safeUnit * safeQuantity);
}

/**
 * req-4 — Filter menu items by category, dietary tag and free-text query using
 * AND semantics; unknown filter values are treated as no filter.
 */
function filterMenu(
  items: MenuItem[],
  category: string,
  tag: string,
  query: string
): MenuItem[] {
  const knownCategories: string[] = ['Breads', 'Pastries', 'Cakes', 'Drinks'];
  const knownTags: string[] = ['gluten', 'dairy', 'nuts', 'egg', 'vegan'];
  const activeCategory: string =
    typeof category === 'string' && knownCategories.indexOf(category) !== -1 ? category : '';
  const activeTag: string =
    typeof tag === 'string' && knownTags.indexOf(tag) !== -1 ? tag : '';
  const activeQuery: string = typeof query === 'string' ? query.trim().toLowerCase() : '';
  const safeItems: MenuItem[] = Array.isArray(items) ? items : [];
  const result: MenuItem[] = [];
  for (let index: number = 0; index < safeItems.length; index += 1) {
    const item: MenuItem = safeItems[index];
    if (activeCategory !== '' && item.category !== activeCategory) {
      continue;
    }
    if (activeTag !== '' && item.tags.indexOf(activeTag as DietaryTag) === -1) {
      continue;
    }
    if (activeQuery !== '') {
      const haystack: string = (item.name + ' ' + item.description).toLowerCase();
      if (haystack.indexOf(activeQuery) === -1) {
        continue;
      }
    }
    result.push(item);
  }
  return result;
}

/**
 * req-4 — Friendly empty-state message when the combined AND filters match
 * nothing, so the page never shows a blank or error list.
 */
function getMenuEmptyState(matchCount: number): string {
  if (matchCount > 0) {
    return '';
  }
  return 'No items match those filters yet \u2014 try another category, dietary tag, or search term.';
}

/**
 * req-5, req-10 — Weekly opening-hours table for the Hours page, derived from the
 * same shared hours table the Home badge reads, ordered Monday through Sunday and
 * tolerating a missing weekday without throwing.
 */
function renderWeeklyHoursTable(table: HoursTable): DayHours[] {
  const week: DayHours[] = table !== undefined && table !== null && Array.isArray(table.week) ? table.week : [];
  const ordered: DayHours[] = [];
  for (let index: number = 0; index < WEEK_ORDER.length; index += 1) {
    const name: string = WEEK_ORDER[index];
    const entry: DayHours | null = findDayHours(week, name);
    if (entry === null) {
      ordered.push({ day: name, open: null, close: null, closed: true });
    } else {
      ordered.push({
        day: entry.day,
        open: entry.open,
        close: entry.close,
        closed: entry.closed || entry.open === null || entry.close === null,
      });
    }
  }
  return ordered;
}

/**
 * req-5 — Human-readable row label for a weekly hours entry, so a day with no
 * hours renders a plain-text marker instead of throwing.
 */
function formatDayHours(entry: DayHours): string {
  if (entry === undefined || entry === null) {
    return 'Closed';
  }
  if (entry.closed || entry.open === null || entry.close === null) {
    return 'Closed';
  }
  return String(entry.open) + '\u2013' + String(entry.close);
}

/**
 * req-5 — Holiday-closures list derived from the shared hours table.
 */
function getHolidayClosures(table: HoursTable): string[] {
  if (table !== undefined && table !== null && Array.isArray(table.holidayClosures)) {
    return table.holidayClosures.slice();
  }
  return [];
}

/**
 * req-2 — Today's fresh-bake highlights for the Home hero, drawn from the static
 * menu data (subset shown so the hero stays short).
 */
function getTodaysHighlights(items: MenuItem[], limit: number): MenuItem[] {
  const safeItems: MenuItem[] = Array.isArray(items) ? items : [];
  const safeLimit: number = Number.isFinite(limit) && limit > 0 ? Math.floor(limit) : 0;
  const highlights: MenuItem[] = [];
  for (let index: number = 0; index < safeItems.length && highlights.length < safeLimit; index += 1) {
    highlights.push(safeItems[index]);
  }
  return highlights;
}

/**
 * req-3 — Render the four fixed menu groups so every inventory item appears
 * under its own category heading with GBP two-decimal pricing and tags.
 */
function renderMenuGroups(items: MenuItem[]): { category: Category; items: MenuItem[] }[] {
  const categories: Category[] = ['Breads', 'Pastries', 'Cakes', 'Drinks'];
  const safeItems: MenuItem[] = Array.isArray(items) ? items : [];
  const groups: { category: Category; items: MenuItem[] }[] = [];
  for (let index: number = 0; index < categories.length; index += 1) {
    const category: Category = categories[index];
    const bucket: MenuItem[] = [];
    for (let inner: number = 0; inner < safeItems.length; inner += 1) {
      if (safeItems[inner].category === category) {
        bucket.push(safeItems[inner]);
      }
    }
    groups.push({ category: category, items: bucket });
  }
  return groups;
}

/**
 * req-2, req-5 — Shared accessor for the site's single hours table so the Home
 * badge and the Hours page render from one identical source.
 */
function getHoursTable(): HoursTable {
  return BAKERY_HOURS_TABLE;
}

/**
 * req-2, req-3 — The static in-app menu data (no database or CMS), read at
 * render time by the Home hero and the Menu page.
 */
function getMenuData(): MenuItem[] {
  return [
    {
      id: 'bread-sourdough',
      name: 'Country Sourdough',
      description: 'Long-fermented, crackling crust, open crumb.',
      pricePence: 480,
