      name: 'Almond Twist',
      description: 'Frangipane and toasted flakes in puff pastry.',
      pricePence: 360,
      category: 'Pastries',
      tags: ['gluten', 'dairy', 'nuts', 'egg'],
    },
    {
      id: 'cake-carrot',
      name: 'Carrot Celebration Cake',
      description: 'Spiced carrot sponge with cream-cheese frosting.',
      pricePence: 2400,
